    n = h if axis == 0 else w
    flags = [any(grid[i][j] != 0 for j in range(w)) if axis == 0
             else any(grid[j][i] != 0 for j in range(h)) for i in range(n)]
    runs = _runs(flags)
    if not runs:
        return []
    lengths = [b - a + 1 for a, b in runs]
    full = Counter(lengths).most_common(1)[0][0]
    offset = full // 2
    return [a + offset for a, _ in runs if a + offset < n]


