 "content": "from collections import Counter


def _runs(flags):
    runs = []
    start = None
    for i, flag in enumerate(flags + [False]):
        if flag and start is None:
            start = i
        elif not flag and start is not None:
            runs.append((start, i))  # half-open
            start = None
    return runs


def _axis_runs(grid, axis):
    h, w = len(grid), len(grid[0])
    n = h if axis == 0 else w
    flags = [any(grid[i][j] != 0 for j in range(w)) if axis == 0
             else any(grid[j][i] != 0 for j in range(h)) for i in range(n)]
    return _runs(flags)


def _usual_size(runs):
    lengths = [b - a for a, b in runs]
    if not lengths:
        return 0
    counts = Counter(lengths)
    # In cropped edge blocks, the full repeated block length is the modal run.
    return max(counts, key=lambda n: (counts[n], n))


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_runs, col_runs = _axis_runs(grid, 0), _axis_runs(grid, 1)
    tile_h, tile_w = _usual_size(row_runs), _usual_size(col_runs)
    if tile_h < 3 or tile_w < 3:
        return out

    # Each repeated square has a one-cell frame. The most common color in the
    # interior patches is their ordinary fill; rarer colors are connection marks.
    inner = []
    tiles = []
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            cells = []
            for dy in range(1, tile_h - 1):
                r = r0 + dy
                if r >= r1 or r >= h:
                    continue
                for dx in range(1, tile_w - 1):
                    c = c0 + dx
                    if c < c1 and c < w:
                        cells.append((dy, dx, grid[r][c]))
                        inner.append(grid[r][c])
            tiles.append((ri, ci, r0, c0, cells))
    if not inner:
        return out
    ordinary = Counter(inner).most_common(1)[0][0]

    # Link equal non-ordinary interior pixels across repeated tiles in each row
    # and column. Existing frame/artwork is preserved; only zero gaps are filled.
    by_row = {}
    by_col = {}
    for ri, ci, r0, c0, cells in tiles:
        for dy, dx, color in cells:
            if color != ordinary:
                by_row.setdefault((ri, dy, dx, color), []).append(c0 + dx)
                by_col.setdefault((ci, dx, dy, color), []).append(r0 + dy)

    for (ri, dy, dx, color), positions in by_row.items():
        positions.sort()
        for a, b in zip(positions, positions[1:]):
            r = row_runs[ri][0] + dy
            for c in range(a + 1, b):
                if out[r][c] == 0:
                    out[r][c] = color

    for (ci, dx, dy, color), positions in by_col.items():
        positions.sort()
        for a, b in zip(positions, positions[1:]):
            c = col_runs[ci][0] + dx
            for r in range(a + 1, b):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
